import { styleText } from 'node:util';
import { GUARD_DOC_TYPE, WORKFLOW_DEFINITION_TYPE, WORKFLOW_INSTANCE_TYPE, resourceGdr, partitionScopeFilter, } from '@sanity/workflow-engine';
import { fail } from './fail.js';
import { deploymentLabel } from './select-deployment.js';
import { formatTable, pluralize, resourceLabel, sectionHeader } from './ui.js';
const CHUNK = 200;
const DEFINITION_ID_TAIL = /([^.]+)\.v(\d+)$/;
const REQUEST_TAG = 'nuke';
export function sweptResources(deployment) {
    return [
        deployment.workflowResource,
        ...(deployment.resourceAliases ?? []).map((binding) => binding.resource),
    ];
}
export function refuseOverlappingNuke(deployments, selected) {
    const swept = new Set(sweptResources(selected).map(resourceGdr));
    const clashing = deployments.filter((candidate) => candidate.name !== selected.name &&
        candidate.partition === selected.partition &&
        sweptResources(candidate).some((resource) => swept.has(resourceGdr(resource))));
    if (clashing.length === 0) {
        return;
    }
    fail(`Refusing to nuke "${deploymentLabel(selected)}" — its guards are indistinguishable ` +
        `from ${clashing.map(deploymentLabel).join(', ')}'s in the shared resource(s).`, `Guard ids embed only the partition, and these deployments share partition "${selected.partition}" plus ` +
        "a swept resource — the sweep would delete the other deployments' live guards. " +
        'Give them distinct partitions first.');
}
export async function resolveNukePlan(args) {
    const { partition, targets } = args;
    const resources = await Promise.all(targets.map((target) => resolveResourcePlan({ partition, target })));
    return { partition, mode: 'partition', resources };
}
async function resolveResourcePlan(args) {
    const { partition, target } = args;
    const { client, holdsEngineDocs } = target;
    const noIds = [];
    const [instanceIds, definitionIds, guardIds] = await Promise.all([
        holdsEngineDocs ? engineDocIds({ client, type: WORKFLOW_INSTANCE_TYPE, partition }) : noIds,
        holdsEngineDocs ? engineDocIds({ client, type: WORKFLOW_DEFINITION_TYPE, partition }) : noIds,
        partitionGuardIds({ client, partition }),
    ]);
    return resourcePlan(target, { instanceIds, definitionIds, guardIds });
}
function resourcePlan(target, ids) {
    return {
        resource: target.resource,
        label: resourceLabel(target.resource),
        client: target.client,
        holdsEngineDocs: target.holdsEngineDocs,
        ...ids,
    };
}
export async function resolveInstanceNukePlan(args) {
    const { instance, partition, targets } = args;
    const resources = await Promise.all(targets.map((target) => resolveInstanceResourcePlan({ instance, target })));
    return { partition, mode: 'instance', resources };
}
async function resolveInstanceResourcePlan(args) {
    const { instance, target } = args;
    const guardIds = await instanceGuardIds({ client: target.client, instanceId: instance.id });
    const holdsInstance = resourceGdr(target.resource) === resourceGdr(instance.resource);
    return resourcePlan(target, {
        instanceIds: holdsInstance ? [instance.id] : [],
        definitionIds: [],
        guardIds,
    });
}
function instanceGuardIds(args) {
    return guardIdsMatching({
        client: args.client,
        match: 'sourceInstanceId == $instanceId || string::startsWith(_id, $guardIdPrefix)',
        params: {
            instanceId: args.instanceId,
            guardIdPrefix: `${GUARD_DOC_TYPE}.${args.instanceId}.`,
        },
    });
}
function engineDocIds(args) {
    return args.client.fetch(`*[_type == $type && ${partitionScopeFilter()}]._id`, { type: args.type, tag: args.partition }, { perspective: 'raw', tag: REQUEST_TAG });
}
function partitionGuardIds(args) {
    const instancePrefix = `${args.partition}.wf-instance.`;
    return guardIdsMatching({
        client: args.client,
        match: 'string::startsWith(sourceInstanceId, $instancePrefix) || string::startsWith(_id, $guardIdPrefix)',
        params: { instancePrefix, guardIdPrefix: `${GUARD_DOC_TYPE}.${instancePrefix}` },
    });
}
function guardIdsMatching(args) {
    return args.client.fetch(`*[_type == $type && (${args.match})]._id`, { type: GUARD_DOC_TYPE, ...args.params }, { perspective: 'raw', tag: REQUEST_TAG });
}
export function involvedTargets(plan) {
    return plan.resources
        .filter((resource) => resourceTotal(resource) > 0)
        .map((resource) => resource.label);
}
function resourceTotal(resource) {
    return resource.instanceIds.length + resource.definitionIds.length + resource.guardIds.length;
}
export function planCounts(plan) {
    const totals = plan.resources.reduce((acc, resource) => ({
        instances: acc.instances + resource.instanceIds.length,
        definitions: acc.definitions + resource.definitionIds.length,
        guards: acc.guards + resource.guardIds.length,
    }), { instances: 0, definitions: 0, guards: 0 });
    return {
        ...totals,
        datasets: involvedTargets(plan).length,
        total: totals.instances + totals.definitions + totals.guards,
    };
}
export function confirmationMatches(input, targets) {
    const typed = new Set(input.trim().split(/\s+/).filter(Boolean));
    const expected = new Set(targets);
    return typed.size === expected.size && [...expected].every((target) => typed.has(target));
}
export function renderNukePlan(plan, { apiHost, heading = `nuke — partition "${plan.partition}"` }) {
    const rows = plan.resources.map((resource) => [
        resource.label,
        resource.holdsEngineDocs ? String(resource.instanceIds.length) : styleText('dim', '—'),
        resource.holdsEngineDocs ? String(resource.definitionIds.length) : styleText('dim', '—'),
        String(resource.guardIds.length),
    ]);
    const definitionsLine = definitionNamesLine(plan.resources.flatMap((resource) => resource.definitionIds));
    return [
        sectionHeader(heading),
        styleText('dim', 'engine-owned documents only — content is never touched'),
        styleText('dim', `API host: ${apiHost}`),
        ...formatTable(['target', 'instances', 'definitions', 'guards'], rows),
        ...(definitionsLine === undefined ? [] : [definitionsLine]),
    ];
}
function countsPhrase(counts) {
    const parts = [
        [counts.instances, 'instance'],
        [counts.definitions, 'definition'],
        [counts.guards, 'guard'],
    ];
    return new Intl.ListFormat('en', { type: 'conjunction' }).format(parts.filter(([count]) => count > 0).map(([count, noun]) => pluralize(count, noun)));
}
export function formatNukePreview(partition, counts) {
    return `This will delete ${countsPhrase(counts)} from partition "${partition}".`;
}
export function formatNukeSummary(partition, counts) {
    return `Deleted from partition "${partition}": ${countsPhrase(counts)}.`;
}
export function formatInstanceNukeSummary(instanceId, counts) {
    if (counts.guards === 0) {
        return `Deleted instance ${instanceId}.`;
    }
    const guards = counts.guards === 1 ? 'its guard' : `its ${counts.guards} guards`;
    return `Deleted instance ${instanceId} and ${guards}.`;
}
const WAVE_ORDER = {
    instance: ['guardIds', 'definitionIds', 'instanceIds'],
    partition: ['instanceIds', 'definitionIds', 'guardIds'],
};
export async function executeNuke(plan) {
    for (const idField of WAVE_ORDER[plan.mode]) {
        for (const resource of plan.resources) {
            await deleteIds(resource.client, resource[idField]);
        }
    }
}
async function deleteIds(client, ids) {
    for (let start = 0; start < ids.length; start += CHUNK) {
        const tx = client.transaction();
        for (const id of ids.slice(start, start + CHUNK))
            tx.delete(id);
        await tx.commit({ tag: REQUEST_TAG });
    }
}
function versionRanges(versions) {
    const runs = [];
    for (const version of [...new Set(versions)].sort((a, b) => a - b)) {
        const run = runs.at(-1);
        if (run !== undefined && version === run.last + 1) {
            run.last = version;
        }
        else {
            runs.push({ first: version, last: version });
        }
    }
    return runs
        .map(({ first, last }) => (first === last ? `v${first}` : `v${first}–v${last}`))
        .join(', ');
}
export function definitionNamesLine(definitionIds) {
    const versionsByName = new Map();
    for (const id of definitionIds) {
        const [, name, version] = DEFINITION_ID_TAIL.exec(id) ?? [];
        if (name === undefined || version === undefined) {
            throw new Error(`Unexpected definition id "${id}"`);
        }
        const versions = versionsByName.get(name) ?? [];
        versions.push(Number(version));
        versionsByName.set(name, versions);
    }
    if (versionsByName.size === 0) {
        return undefined;
    }
    const entries = [...versionsByName.keys()]
        .sort()
        .map((name) => `${name} (${versionRanges(versionsByName.get(name) ?? [])})`);
    return `definitions: ${entries.join(', ')}`;
}
